"""Adversarial search for x > y (x more mixed) with S(x) <= S(y).  Pairs: y = spectrum, x = T-transform of y (Schur order is generated by these), big and tiny steps,
then random doubly stochastic images.  Score = (S(x)-S(y)) / (|S(x)|+|S(y)|+1) / (relative step); local descent drives it down.  Worst points rechecked with the paper's Theorem 5.3."""
import sys; import os; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import mpmath as mp, random, math
from multiprocessing import Pool
import fidelity as F
mp.mp.dps=60
def norm(l): s=mp.fsum(l); return [x/s for x in l]
def spectrum(rng,n,ext): return norm([mp.mpf(10)**(-rng.uniform(0,ext)) for _ in range(n)])
def ttr(l,i,j,t):         # move toward equality: t in (0,1/2]
    l=list(l); a,b=l[i],l[j]; l[i]=(1-t)*a+t*b; l[j]=t*a+(1-t)*b; return l
def jitter(l):            # closed() needs distinct entries for the triangle term: separate coincidences by 1e-20 (smooth function; effect 1e-20)
    l=list(l)
    for i in range(len(l)):
        for j in range(i):
            if abs(l[i]/l[j]-1)<mp.mpf(10)**-22: l[i]*=1+mp.mpf(10)**-20*(i+1)
    return l
def score(S,par,n):
    lam,i,j,t=par; x=ttr(lam,i,j,t); gap=abs(lam[i]-lam[j])
    if gap==0: return None
    d=S(jitter(x))-S(jitter(lam)); return d, d/(abs(S(jitter(lam)))+1)/(t*(gap/max(lam[i],lam[j]))**2)
def run(a):
    seed,n,kind=a; rng=random.Random(seed); ext=rng.choice([.3,1,3,6,10,16])
    if kind=='wyd': b=mp.mpf(rng.choice([rng.uniform(-1,0),rng.uniform(0,1),rng.uniform(1,2),1-10**-rng.uniform(1,5),.5+10**-rng.uniform(1,4),2-10**-rng.uniform(0,6),2,-1])); 
    else: b=kind
    if b in (0,1,mp.mpf(1)/2): return None
    S=(lambda l: F.closed(l,b)) if kind=='wyd' else (lambda l: bures(l))
    lam=spectrum(rng,n,ext); i,j=rng.sample(range(n),2); t=mp.mpf(rng.choice([.5,.25,.01,1e-4])); cur=score(S,(lam,i,j,t),n)
    if cur is None: return None
    best=(cur[1],cur[0],lam,i,j,t)
    for it in range(40 if kind=='wyd' else 15):      # local descent
        sc=rng.choice([1,.3,.05]); lam2=norm([x*mp.mpf(10)**rng.gauss(0,sc) for x in best[2]]); t2=mp.mpf(min(.5,max(1e-5,float(best[5])*10**rng.gauss(0,sc))))
        c=score(S,(lam2,i,j,t2),n)
        if c and c[1]<best[0]: best=(c[1],c[0],lam2,i,j,t2)
    return (float(best[0]),float(mp.sign(best[1])),str(b),n,[mp.nstr(x,12) for x in best[2]],i,j,mp.nstr(best[5],6),best)
def bures(E):
    c0=F.cf; F.cf=lambda x,y,b: 2/(x+y)
    try: return F.thm53(E,None)
    finally: F.cf=c0
if __name__=="__main__":
    mode=sys.argv[1]; N=int(sys.argv[2])
    jobs=[(s,[2,3,3,4,5,6][s%6],'wyd') for s in range(N)] if mode=='wyd' else [(s,3,'bures') for s in range(N)]
    with Pool(6) as p: R=[r for r in p.imap_unordered(run,jobs,chunksize=4) if r]
    R.sort(key=lambda r:r[0]); bad=[r for r in R if r[1]<=0]
    print(mode,"descents",len(R),"VIOLATIONS" ,len(bad)," lowest scores:")
    for r in R[:6]: print("   score %.3e sign %+d beta=%s n=%d lam=%s pair=(%d,%d) t=%s"%(r[0],r[1],r[2][:12],r[3],r[4],r[5],r[6],r[7]))
    if mode=='wyd':
        mn=0; k=0; worst=0
        for r in [x for x in R if x[3]<=4][:12]:
            b=mp.mpf(r[2]); _,_,lam,i,j,t=r[8]; x=jitter(ttr(lam,i,j,t)); y=jitter(lam); mp.mp.dps=110
            d1=F.thm53(x,b)-F.thm53(y,b); d2=F.closed(x,b)-F.closed(y,b); mp.mp.dps=60; k+=1; mn+=(d1<=0); worst=max(worst,abs(d1/d2-1))
        print("   Theorem 5.3 recheck of",k,"lowest points with n<=4: violations",mn," worst rel. difference from closed form",mp.nstr(worst,2))
